"""Billing for bookings. Rate lookups are billed, so the charge is remembered."""
import rates


class BookingBill:
    def __init__(self):
        self._bookings = []
        self._charge = None

    def add(self, booking):
        """Add one booking to the bill."""
        self._bookings.append(booking)

    def charge(self):
        """Return the total charge: nights times the rate for each booking's hotel.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.nights * rates.rate_for(x.hotel) for x in self._bookings)
        return self._charge


def largest_nights(bookings):
    """Return the largest nights, or None when there are no bookings."""
    values = [x.nights for x in bookings]
    return max(values) if values else None
